window.D426_GUIDE = [{"id": "01-database-basics", "n": 1, "title": "Database basics", "time": "3 minutes", "topic": "basics", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li><strong>Query processor</strong> plans the query. <strong>Storage manager</strong> reads and writes files. <strong>Transaction manager</strong> keeps things consistent.</li>\n<li>The <strong>DBA</strong> secures the database against unauthorized users.</li>\n<li><strong>Authorization</strong> limits users to specific tables, columns, or rows.</li>\n</ul></div>\n<h2>How a query moves through the system</h2>\n<pre><code class=\"language-mermaid\">flowchart TD\n  A[&quot;Application&lt;br/&gt;sends SQL, gets results&quot;] --&gt; Q[&quot;Query processor&lt;br/&gt;interprets + optimizes&quot;]\n  Q --&gt; S[&quot;Storage manager&lt;br/&gt;file I/O, uses indexes&quot;]\n  S --&gt; D[(&quot;Database files&lt;br/&gt;tables + indexes&quot;)]\n  T[&quot;Transaction manager&lt;br/&gt;prevents conflicts,&lt;br/&gt;restores after failure&quot;] -.oversees.-&gt; Q\n  T -.oversees.-&gt; S\n</code></pre>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Job</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Query processor</strong></td>\n<td>Interprets the query, builds a plan, runs <strong>query optimization</strong>, returns results</td>\n</tr>\n<tr>\n<td><strong>Storage manager</strong></td>\n<td>Turns the plan into low-level file-system commands; uses <strong>indexes</strong> to find data fast</td>\n</tr>\n<tr>\n<td><strong>Transaction manager</strong></td>\n<td>Prevents conflicts between concurrent transactions; restores consistency after a failure</td>\n</tr>\n<tr>\n<td><strong>Log</strong></td>\n<td>Records every insert, update, and delete for recovery</td>\n</tr>\n<tr>\n<td><strong>Catalog</strong> (data dictionary)</td>\n<td>Metadata about tables, columns, indexes</td>\n</tr>\n</tbody>\n</table>\n<h2>People and rules</h2>\n<ul>\n<li><strong>Database application:</strong> software that helps business users work with a database.</li>\n<li><strong>Database administrator (DBA):</strong> secures the system and enforces access and availability procedures.</li>\n<li>Other roles: <strong>database designer</strong> (structure), <strong>database programmer</strong> (writes code that uses SQL), <strong>database user</strong> (consumes the data).</li>\n<li><strong>Rules:</strong> data must stay consistent with structural and business rules.</li>\n<li><strong>API:</strong> lets Python, Java, and other languages run SQL.</li>\n<li><strong>MySQL</strong> is relational and open source. <strong>MongoDB</strong> is NoSQL and open source.</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>Query <em>optimization</em> belongs to the <strong>query processor</strong>, not the storage manager.</li>\n<li>Recovery after a crash is the <strong>transaction manager</strong>.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. Which component translates the plan into file-system commands?</summary><div class=\"ans\"><p><strong>Storage manager.</strong></p></div></details>\n<details class=\"check\"><summary>2. Who secures the database against unauthorized users?</summary><div class=\"ans\"><p><strong>The database administrator (DBA).</strong></p></div></details>\n<details class=\"check\"><summary>3. What prevents two concurrent transactions from colliding?</summary><div class=\"ans\"><p><strong>The transaction manager.</strong></p></div></details>"}, {"id": "02-relational-model", "n": 2, "title": "Relational model", "time": "3 minutes", "topic": "relational", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li>A table = a name + a fixed sequence of columns + a varying <strong>set</strong> of rows.</li>\n<li>Rows have <strong>no order</strong> (it's a set). Tuples <strong>do</strong> have order.</li>\n<li><strong>Data independence:</strong> how data is stored never changes query results.</li>\n</ul></div>\n<h2>The building blocks</h2>\n<ul>\n<li>A table needs <strong>at least one column</strong>, but can have <strong>zero rows</strong> (an <strong>empty table</strong>).</li>\n<li><strong>Column:</strong> has a name and a data type.</li>\n<li><strong>Row:</strong> an unnamed tuple of values, one per column.</li>\n<li><strong>Cell:</strong> one column of one row.</li>\n<li><strong>Tuple:</strong> ordered, so (a, b, c) ≠ (c, b, a).</li>\n<li><strong>Data type:</strong> a named set of values that column values come from.</li>\n</ul>\n<h2>Same thing, three names</h2>\n<table>\n<thead>\n<tr>\n<th>Relational</th>\n<th>SQL</th>\n<th>Old file term</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Relation</td>\n<td>Table</td>\n<td>File</td>\n</tr>\n<tr>\n<td>Tuple</td>\n<td>Row</td>\n<td>Record</td>\n</tr>\n<tr>\n<td>Attribute</td>\n<td>Column</td>\n<td>Field</td>\n</tr>\n</tbody>\n</table>\n<h2>Relational algebra, the three to know</h2>\n<table>\n<thead>\n<tr>\n<th>Operation</th>\n<th>Does</th>\n<th>SQL feel</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Select</strong></td>\n<td>Picks <strong>rows</strong></td>\n<td><code>WHERE</code></td>\n</tr>\n<tr>\n<td><strong>Project</strong></td>\n<td>Picks <strong>columns</strong></td>\n<td><code>SELECT Col1, Col2</code></td>\n</tr>\n<tr>\n<td><strong>Product</strong></td>\n<td>Every row × every row (Table1 × Table2)</td>\n<td><code>CROSS JOIN</code></td>\n</tr>\n</tbody>\n</table>\n<p>Trick: <strong>P</strong>roject = <strong>P</strong>illars (columns stand up).</p>\n<h2>Two kinds of rules</h2>\n<ul>\n<li><strong>Relational (structural) rules</strong> apply to every relational database: unique primary key, unique column names, no duplicate rows.</li>\n<li><strong>Business rules</strong> come from business policy and apply to one database: \"a course in a registration must exist in the catalog.\"</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>\"Attribute\" = column, not row.</li>\n<li>A table with no rows is still valid.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. A row is also called a…?</summary><div class=\"ans\"><p><strong>Tuple</strong> (or record).</p></div></details>\n<details class=\"check\"><summary>2. Why do rows have no inherent order?</summary><div class=\"ans\"><p><strong>A table is a set of rows</strong>, and sets are unordered.</p></div></details>\n<details class=\"check\"><summary>3. What principle says physical storage changes never change results?</summary><div class=\"ans\"><p><strong>Data independence.</strong></p></div></details>"}, {"id": "03-sql-language-and-types", "n": 3, "title": "SQL language and data types", "time": "5 minutes", "topic": "sql", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li>Five sublanguages: <strong>DDL</strong> (structure), <strong>DQL</strong> (SELECT), <strong>DML</strong> (change data), <strong>DCL</strong> (access), <strong>DTL</strong> (transactions).</li>\n<li><strong>DECIMAL(M, D)</strong> = M total digits, D after the decimal.</li>\n<li>Integer sizes: TINYINT 1 byte · SMALLINT 2 · MEDIUMINT 3 · INT 4 · BIGINT 8.</li>\n</ul></div>\n<h2>The five sublanguages</h2>\n<table>\n<thead>\n<tr>\n<th>Sublanguage</th>\n<th>Job</th>\n<th>Statements</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>DDL</strong> Data Definition</td>\n<td>Defines structure</td>\n<td>CREATE, ALTER, DROP</td>\n</tr>\n<tr>\n<td><strong>DQL</strong> Data Query</td>\n<td>Retrieves data</td>\n<td>SELECT</td>\n</tr>\n<tr>\n<td><strong>DML</strong> Data Manipulation</td>\n<td>Changes data</td>\n<td>INSERT, UPDATE, DELETE</td>\n</tr>\n<tr>\n<td><strong>DCL</strong> Data Control</td>\n<td>Controls access</td>\n<td>GRANT, REVOKE</td>\n</tr>\n<tr>\n<td><strong>DTL</strong> Data Transaction</td>\n<td>Manages transactions</td>\n<td>COMMIT, ROLLBACK</td>\n</tr>\n</tbody>\n</table>\n<h2>Parts of a statement</h2>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Literal</strong> (explicit value)</td>\n<td><code>'String'</code>, <code>\"String\"</code>, <code>123</code>, <code>x'0fa2'</code></td>\n</tr>\n<tr>\n<td><strong>Keyword</strong> (special meaning)</td>\n<td><code>SELECT</code>, <code>FROM</code>, <code>WHERE</code></td>\n</tr>\n<tr>\n<td><strong>Identifier</strong> (object name)</td>\n<td><code>City</code>, <code>Name</code>, <code>Population</code></td>\n</tr>\n<tr>\n<td><strong>Expression</strong> (evaluates to one value)</td>\n<td><code>Population &gt; 1000000 OR Name = 'Tokyo'</code></td>\n</tr>\n<tr>\n<td><strong>Comment</strong> (ignored)</td>\n<td><code>-- one line</code>, <code>/* many lines */</code></td>\n</tr>\n</tbody>\n</table>\n<h2>Data types</h2>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Stores</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>INT / INTEGER</td>\n<td>Whole numbers, 4 bytes</td>\n<td>34, -739448</td>\n</tr>\n<tr>\n<td>DECIMAL(M, D)</td>\n<td>M digits total, D after the point</td>\n<td>DECIMAL(5, 2) → 999.99 max</td>\n</tr>\n<tr>\n<td>VARCHAR(N)</td>\n<td>Text, 0 to N characters</td>\n<td>'Seattle'</td>\n</tr>\n<tr>\n<td>CHAR(N)</td>\n<td>Text, fixed length N</td>\n<td>'PA' in CHAR(2)</td>\n</tr>\n<tr>\n<td>DATE</td>\n<td>Year, month, day</td>\n<td>'2026-11-08'</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n<th>Integer</th>\n<th>Bytes</th>\n<th>Signed</th>\n<th>Unsigned</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>TINYINT</td>\n<td>1</td>\n<td>-128 to 127</td>\n<td>0 to 255</td>\n</tr>\n<tr>\n<td>SMALLINT</td>\n<td>2</td>\n<td>-32,768 to 32,767</td>\n<td>0 to 65,535</td>\n</tr>\n<tr>\n<td>MEDIUMINT</td>\n<td>3</td>\n<td>-8,388,608 to 8,388,607</td>\n<td>0 to 16,777,215</td>\n</tr>\n<tr>\n<td>INT</td>\n<td>4</td>\n<td>about ±2.1 billion</td>\n<td>0 to 4,294,967,295</td>\n</tr>\n<tr>\n<td>BIGINT</td>\n<td>8</td>\n<td>-2^63 to 2^63 - 1</td>\n<td>0 to 2^64 - 1</td>\n</tr>\n</tbody>\n</table>\n<h2>Operators worth remembering</h2>\n<ul>\n<li><code>%</code> modulo = remainder: <code>5 % 2</code> → <code>1</code></li>\n<li><code>^</code> = power in the course table: <code>5^2</code> → <code>25</code></li>\n<li><code>'2019-08-13' &gt; '2021-08-13'</code> → FALSE (dates compare in order)</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>SELECT is <strong>DQL</strong>, not DML. (Some study sheets lump it into DML; the five-sublanguage model doesn't.)</li>\n<li>DECIMAL(5, 2) is <strong>5 total</strong> digits, not 5 before the decimal.</li>\n<li>Real MySQL treats <code>^</code> as XOR, but answer with the course table.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. GRANT belongs to which sublanguage?</summary><div class=\"ans\"><p><strong>DCL.</strong></p></div></details>\n<details class=\"check\"><summary>2. How many bytes is SMALLINT?</summary><div class=\"ans\"><p><strong>2.</strong></p></div></details>\n<details class=\"check\"><summary>3. Largest value DECIMAL(5, 2) can hold?</summary><div class=\"ans\"><p><strong>999.99.</strong></p></div></details>"}, {"id": "04-core-statements", "n": 4, "title": "Core statements", "time": "4 minutes", "topic": "statements", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li><strong>DELETE</strong> = chosen rows · <strong>TRUNCATE</strong> = all rows · <strong>DROP</strong> = the whole table.</li>\n<li>UPDATE or DELETE <strong>without WHERE</strong> changes every row.</li>\n<li><strong>MERGE</strong> copies from a <strong>source</strong> table into a <strong>target</strong> table.</li>\n</ul></div>\n<h2>What each one does</h2>\n<table>\n<thead>\n<tr>\n<th>Statement</th>\n<th>Does</th>\n<th>Watch for</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>CREATE TABLE</td>\n<td>Makes a table: name, columns, data types</td>\n<td>Constraints go here too</td>\n</tr>\n<tr>\n<td>DROP TABLE</td>\n<td>Deletes the table <strong>and</strong> its rows</td>\n<td>Structure is gone</td>\n</tr>\n<tr>\n<td>ALTER TABLE</td>\n<td>ADD, DROP, or CHANGE columns</td>\n<td>Also adds/drops constraints</td>\n</tr>\n<tr>\n<td>INSERT</td>\n<td>Adds rows</td>\n<td>Skip values for auto-increment keys</td>\n</tr>\n<tr>\n<td>UPDATE</td>\n<td>Changes rows with SET</td>\n<td>No WHERE = every row</td>\n</tr>\n<tr>\n<td>DELETE</td>\n<td>Removes rows</td>\n<td>No WHERE = every row</td>\n</tr>\n<tr>\n<td>TRUNCATE</td>\n<td>Removes all rows, keeps the table</td>\n<td>≈ DELETE with no WHERE</td>\n</tr>\n<tr>\n<td>MERGE</td>\n<td>Source → target</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n<h2>See them in action</h2>\n<pre><code class=\"language-sql\">CREATE TABLE Employee (\n  ID        INT AUTO_INCREMENT,\n  Name      VARCHAR(60) NOT NULL,\n  Salary    DECIMAL(8, 2),\n  HireDate  DATE,\n  DeptCode  INT,\n  PRIMARY KEY (ID),\n  FOREIGN KEY (DeptCode) REFERENCES Department(Code) ON DELETE SET NULL\n);\n\nINSERT INTO Employee (Name, Salary, HireDate) VALUES ('Sam Snead', 35000.00, '2026-01-15');\nUPDATE Employee SET Salary = 40000 WHERE ID = 1;\nDELETE FROM Employee WHERE ID = 1;\nALTER TABLE Employee ADD Phone VARCHAR(15);\nDROP TABLE Employee;\n</code></pre>\n<p>A syntax error in the MySQL Command-Line Client returns an <strong>error code and description</strong>.</p>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>DROP removes the table itself; TRUNCATE leaves an empty table.</li>\n<li>The INSERT above skips <code>ID</code> on purpose: it's auto-increment.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. UPDATE Employee SET Salary = 0; — what happens?</summary><div class=\"ans\"><p><strong>Every row's salary becomes 0.</strong> No WHERE clause.</p></div></details>\n<details class=\"check\"><summary>2. Which statement removes all rows but keeps the table?</summary><div class=\"ans\"><p><strong>TRUNCATE.</strong></p></div></details>\n<details class=\"check\"><summary>3. Which clause does ALTER TABLE use to rename/modify a column?</summary><div class=\"ans\"><p><strong>CHANGE</strong> (alongside ADD and DROP).</p></div></details>"}, {"id": "05-keys-and-constraints", "n": 5, "title": "Keys and constraints", "time": "5 minutes", "topic": "keys", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li><strong>Primary key</strong> identifies each row: unique and not NULL.</li>\n<li><strong>Foreign key</strong> points at a primary key: same data type, name can differ.</li>\n<li>Four fix-ups for broken references: <strong>RESTRICT, SET NULL, SET DEFAULT, CASCADE</strong>.</li>\n</ul></div>\n<h2>Primary keys</h2>\n<ul>\n<li><strong>Simple</strong> = one column. <strong>Composite</strong> = several columns.</li>\n<li><strong>Auto-increment column:</strong> gets the next number automatically on insert.</li>\n<li>Two classic insert mistakes:<ol>\n<li>Supplying a value for an auto-increment key.</li>\n<li>Leaving out the value for a key that is <em>not</em> auto-increment.</li>\n</ol>\n</li>\n</ul>\n<h2>Foreign keys and referential integrity</h2>\n<ul>\n<li>Declared with <code>FOREIGN KEY (...) REFERENCES Table(...)</code>.</li>\n<li><strong>Referential integrity:</strong> every foreign key value matches an existing primary key, or is NULL.</li>\n</ul>\n<table>\n<thead>\n<tr>\n<th>Action</th>\n<th>When a change would break a reference…</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>RESTRICT</strong></td>\n<td>Reject the change</td>\n</tr>\n<tr>\n<td><strong>SET NULL</strong></td>\n<td>Set the broken foreign keys to NULL</td>\n</tr>\n<tr>\n<td><strong>SET DEFAULT</strong></td>\n<td>Set them to the column's default value</td>\n</tr>\n<tr>\n<td><strong>CASCADE</strong></td>\n<td>Carry the change through (ON DELETE CASCADE deletes the child rows)</td>\n</tr>\n</tbody>\n</table>\n<pre><code class=\"language-sql\">FOREIGN KEY (DeptCode) REFERENCES Department(Code)\n  ON DELETE CASCADE\n  ON UPDATE SET NULL\n</code></pre>\n<h2>Constraints</h2>\n<p>A <strong>constraint</strong> is a rule on allowed values. Break it and the statement is rejected.</p>\n<table>\n<thead>\n<tr>\n<th>Constraint</th>\n<th>Rule</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>NOT NULL</td>\n<td>Can't be empty</td>\n</tr>\n<tr>\n<td>UNIQUE</td>\n<td>No duplicates</td>\n</tr>\n<tr>\n<td>PRIMARY KEY</td>\n<td>Unique + not NULL</td>\n</tr>\n<tr>\n<td>FOREIGN KEY</td>\n<td>Must match a referenced key</td>\n</tr>\n<tr>\n<td>CHECK</td>\n<td>Must pass a condition: <code>CHECK (Salary &gt; 0)</code></td>\n</tr>\n<tr>\n<td>DEFAULT</td>\n<td>Value used when none is given</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>Column constraint:</strong> written right after one column's definition.</li>\n<li><strong>Table constraint:</strong> its own clause; can cover several columns, like <code>PRIMARY KEY (A, B)</code>.</li>\n<li>Change them later with <code>ALTER TABLE ... ADD / DROP / CHANGE</code>.</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>Foreign key and primary key <strong>names may differ</strong>; <strong>types must match</strong>.</li>\n<li>CASCADE <em>propagates</em>. RESTRICT <em>rejects</em>. Don't swap them.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. Deleting a department should delete its employees too. Which action?</summary><div class=\"ans\"><p><strong>ON DELETE CASCADE.</strong></p></div></details>\n<details class=\"check\"><summary>2. Which constraint enforces \"Salary must be positive\"?</summary><div class=\"ans\"><p><strong>CHECK (Salary &gt; 0).</strong></p></div></details>\n<details class=\"check\"><summary>3. Primary key made of two columns?</summary><div class=\"ans\"><p><strong>Composite primary key.</strong></p></div></details>"}, {"id": "06-writing-queries", "n": 6, "title": "Writing queries", "time": "5 minutes", "topic": "queries", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li>Clause order: <strong>SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY</strong>.</li>\n<li><strong>WHERE</strong> filters rows; <strong>HAVING</strong> filters groups.</li>\n<li>LIKE: <code>%</code> = any number of characters, <code>_</code> = exactly one.</li>\n</ul></div>\n<h2>The whole thing in one query</h2>\n<pre><code class=\"language-sql\">SELECT   DeptCode, COUNT(*) AS Headcount, AVG(Salary) AS AvgPay\nFROM     Employee\nWHERE    Salary &gt; 30000          -- 1. filter ROWS\nGROUP BY DeptCode                -- 2. one group per department\nHAVING   COUNT(*) &gt;= 5           -- 3. filter GROUPS\nORDER BY Headcount DESC;         -- 4. sort what's left\n</code></pre>\n<p>Mnemonic: <strong>S</strong>weaty <strong>F</strong>eet <strong>W</strong>ill <strong>G</strong>ive <strong>H</strong>orrible <strong>O</strong>dors.</p>\n<h2>Filtering</h2>\n<table>\n<thead>\n<tr>\n<th>Operator</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>BETWEEN</td>\n<td>Inclusive range</td>\n<td><code>Age BETWEEN 18 AND 30</code> = <code>&gt;= 18 AND &lt;= 30</code></td>\n</tr>\n<tr>\n<td>IN</td>\n<td>Any value in a list</td>\n<td><code>State IN ('PA', 'NJ')</code></td>\n</tr>\n<tr>\n<td>LIKE <code>%</code></td>\n<td>Any number of characters (even zero)</td>\n<td><code>'L%t'</code> → Lt, Lot, Lift</td>\n</tr>\n<tr>\n<td>LIKE <code>_</code></td>\n<td>Exactly one character</td>\n<td><code>'L_t'</code> → Lot, Lit (not Lt, Loot)</td>\n</tr>\n<tr>\n<td>IS NULL</td>\n<td>Tests for NULL</td>\n<td><code>= NULL</code> never matches</td>\n</tr>\n</tbody>\n</table>\n<h2>Sorting and naming</h2>\n<ul>\n<li><strong>ORDER BY</strong> sorts ascending by default. Add <strong>DESC</strong> for descending.</li>\n<li><strong>Alias:</strong> a temporary name with optional <strong>AS</strong>: <code>Salary AS Pay</code>.</li>\n</ul>\n<h2>Functions</h2>\n<table>\n<thead>\n<tr>\n<th>Function</th>\n<th>Example → result</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>ABS(n)</td>\n<td><code>ABS(-5)</code> → 5</td>\n</tr>\n<tr>\n<td>LOWER(s)</td>\n<td><code>LOWER('MySQL')</code> → 'mysql'</td>\n</tr>\n<tr>\n<td>TRIM(s)</td>\n<td><code>TRIM('  test  ')</code> → 'test'</td>\n</tr>\n<tr>\n<td>HOUR / MINUTE / SECOND</td>\n<td><code>HOUR('22:11:45')</code> → 22</td>\n</tr>\n<tr>\n<td>UPPER(s)</td>\n<td><code>UPPER('sql')</code> → 'SQL'</td>\n</tr>\n<tr>\n<td>CONCAT(s1, s2, ...)</td>\n<td><code>CONCAT('Data', 'base')</code> → 'Database'</td>\n</tr>\n<tr>\n<td>SUBSTRING(s, pos, len)</td>\n<td><code>SUBSTRING('Database', 1, 4)</code> → 'Data'</td>\n</tr>\n<tr>\n<td>REPLACE(s, from, to)</td>\n<td><code>REPLACE('cats and dogs', 'and', 'or')</code> → 'cats or dogs'</td>\n</tr>\n</tbody>\n</table>\n<h2>Aggregates</h2>\n<p><strong>COUNT, MIN, MAX, SUM, AVG</strong> turn many rows into one value.</p>\n<ul>\n<li>They only see rows that pass WHERE.</li>\n<li>With GROUP BY, they compute once per group.</li>\n<li>They skip NULLs; <code>COUNT(*)</code> still counts every row.</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>Filtering on an aggregate (<code>COUNT(*) &gt; 5</code>) needs <strong>HAVING</strong>, not WHERE.</li>\n<li>BETWEEN <strong>includes</strong> both ends.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. Which clause comes right after GROUP BY?</summary><div class=\"ans\"><p><strong>HAVING.</strong></p></div></details>\n<details class=\"check\"><summary>2. Does LIKE 'L_t' match \"Loot\"?</summary><div class=\"ans\"><p><strong>No.</strong> <code>_</code> is exactly one character.</p></div></details>\n<details class=\"check\"><summary>3. AVG skips which values?</summary><div class=\"ans\"><p><strong>NULLs.</strong></p></div></details>"}, {"id": "07-joins-subqueries-views", "n": 7, "title": "Joins, subqueries, and views", "time": "5 minutes", "topic": "joins", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li>The join type decides what happens to <strong>unmatched</strong> rows.</li>\n<li><strong>LEFT</strong> keeps all left rows; <strong>RIGHT</strong> keeps all right rows; <strong>FULL</strong> keeps everything.</li>\n<li>A <strong>materialized view</strong> stores its data and must be refreshed.</li>\n</ul></div>\n<h2>Which rows survive?</h2>\n<table>\n<thead>\n<tr>\n<th>Join</th>\n<th>Keeps</th>\n<th>Unmatched side shows</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>INNER</td>\n<td>Only matches</td>\n<td>Dropped</td>\n</tr>\n<tr>\n<td>LEFT</td>\n<td>All left + matching right</td>\n<td>NULL in right columns</td>\n</tr>\n<tr>\n<td>RIGHT</td>\n<td>All right + matching left</td>\n<td>NULL in left columns</td>\n</tr>\n<tr>\n<td>FULL</td>\n<td>Everything from both</td>\n<td>NULL wherever no match</td>\n</tr>\n<tr>\n<td>CROSS</td>\n<td>Every combination; <strong>no ON clause</strong></td>\n<td>n/a</td>\n</tr>\n</tbody>\n</table>\n<pre><code class=\"language-sql\">SELECT E.Name, D.Name AS Department\nFROM Employee AS E\nLEFT JOIN Department AS D ON E.DeptCode = D.Code;\n</code></pre>\n<h2>More join words</h2>\n<ul>\n<li><strong>Outer join</strong> = LEFT, RIGHT, or FULL (anything that keeps unmatched rows).</li>\n<li><strong>Equijoin</strong> uses <code>=</code>. <strong>Non-equijoin</strong> uses <code>&lt;</code>, <code>&gt;</code>, and so on.</li>\n<li><strong>Self-join:</strong> a table joined to itself (employee → manager). Use aliases.</li>\n<li><strong>UNION</strong> stacks two SELECT results into one. MySQL has no FULL JOIN, so you do LEFT JOIN UNION RIGHT JOIN.</li>\n</ul>\n<h2>Subqueries</h2>\n<p>A query inside a query. Also called a <strong>nested</strong> or <strong>inner</strong> query.</p>\n<pre><code class=\"language-sql\">SELECT Name FROM Employee\nWHERE Salary &gt; (SELECT AVG(Salary) FROM Employee);\n</code></pre>\n<h2>Views</h2>\n<ul>\n<li><strong>View:</strong> a table defined by a SELECT. The tables it reads are its <strong>base tables</strong>.</li>\n<li><strong>Materialized view:</strong> stores its data; must be <strong>refreshed</strong> when base tables change.</li>\n<li><strong>WITH CHECK OPTION:</strong> rejects inserts/updates through the view that don't match the view's WHERE.</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>CROSS JOIN has <strong>no ON clause</strong>.</li>\n<li>\"Outer join\" never means INNER.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. You need every employee, even ones with no department. Which join (Employee on the left)?</summary><div class=\"ans\"><p><strong>LEFT JOIN.</strong></p></div></details>\n<details class=\"check\"><summary>2. What do you call a join of a table to itself?</summary><div class=\"ans\"><p><strong>Self-join.</strong></p></div></details>\n<details class=\"check\"><summary>3. Which view type must be refreshed?</summary><div class=\"ans\"><p><strong>Materialized view.</strong></p></div></details>"}, {"id": "08-design-and-er-modeling", "n": 8, "title": "Design and ER modeling", "time": "6 minutes", "topic": "design", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li>Three phases: <strong>Analysis → Logical design → Physical design</strong>.</li>\n<li>Eight steps: four in analysis, four in logical design. The last analysis step is <strong>supertype/subtype</strong>.</li>\n<li>Crow's foot: <strong>circle = 0, line = 1, crow's foot = many</strong>.</li>\n<li>Name a relationship by asking \"one or many?\" <strong>from both sides</strong>.</li>\n</ul></div>\n<h2>Phases and steps</h2>\n<pre><code class=\"language-mermaid\">flowchart TD\n  subgraph A[&quot;Analysis: ER model, no specific DB&quot;]\n    a1[&quot;1 Discover entities,&lt;br/&gt;relationships, attributes&quot;] --&gt; a2[&quot;2 Determine cardinality&quot;] --&gt; a3[&quot;3 Strong vs weak entities&quot;] --&gt; a4[&quot;4 Supertype / subtype&quot;]\n  end\n  subgraph L[&quot;Logical design: tables + keys&quot;]\n    l5[&quot;5 Implement entities&quot;] --&gt; l6[&quot;6 Implement relationships&quot;] --&gt; l7[&quot;7 Implement attributes&quot;] --&gt; l8[&quot;8 Apply normal form&quot;]\n  end\n  a4 --&gt; l5\n  l8 --&gt; P[&quot;Physical design&lt;br/&gt;indexes, storage&quot;]\n</code></pre>\n<ul>\n<li><strong>Analysis</strong> is also called conceptual design, ER modeling, or requirements definition.</li>\n<li><strong>Physical design</strong> never changes results, only speed.</li>\n</ul>\n<h2>ER building blocks</h2>\n<table>\n<thead>\n<tr>\n<th>Thing</th>\n<th>What it is</th>\n<th>Becomes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Entity</strong></td>\n<td>Person, place, product, concept, activity (rectangle)</td>\n<td>Table</td>\n</tr>\n<tr>\n<td><strong>Relationship</strong></td>\n<td>A statement about two entities</td>\n<td>Foreign key</td>\n</tr>\n<tr>\n<td><strong>Attribute</strong></td>\n<td>A descriptive property</td>\n<td>Column</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>Reflexive relationship:</strong> an entity related to itself.</li>\n<li><strong>Type vs instance:</strong> \"all employees\" is a type; \"Sam Snead\" is an instance.</li>\n<li><strong>Intangible entity:</strong> in the model, but not tracked with data.</li>\n</ul>\n<h2>Cardinality</h2>\n<ul>\n<li><strong>Relationship maximum:</strong> the most instances that can relate (one or many).</li>\n<li><strong>Relationship minimum:</strong> the fewest (zero = optional, one = required).</li>\n<li><strong>Attribute notation:</strong> <code>Name 1(1)</code> = singular, required. <code>Phone M(0)</code> = plural, optional.</li>\n</ul>\n<table>\n<thead>\n<tr>\n<th>Crow's foot</th>\n<th>Means</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Circle</td>\n<td>Zero</td>\n</tr>\n<tr>\n<td>Short line</td>\n<td>One</td>\n</tr>\n<tr>\n<td>Three lines</td>\n<td>Many</td>\n</tr>\n</tbody>\n</table>\n<h2>Naming the relationship (exam favorite)</h2>\n<p>The question's wording can trick you. <strong>Ask it from both sides</strong>, out loud:</p>\n<ol>\n<li>\"Can one A have many B?\"</li>\n<li>\"Can one B have many A?\"</li>\n</ol>\n<table>\n<thead>\n<tr>\n<th>Both answers</th>\n<th>Relationship</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Yes and yes</td>\n<td><strong>Many-to-many (M:M)</strong></td>\n<td>Employees ↔ projects, students ↔ classes, doctors ↔ patients</td>\n</tr>\n<tr>\n<td>Yes and no</td>\n<td><strong>One-to-many / many-to-one</strong></td>\n<td>Many employees → one office building</td>\n</tr>\n<tr>\n<td>No and no</td>\n<td><strong>One-to-one (1:1)</strong></td>\n<td>Employee ↔ desk, when desks are never shared</td>\n</tr>\n</tbody>\n</table>\n<p>\"Employee works on project\" <em>sounds</em> one-to-one. It isn't: projects have many employees, and employees can be on many projects.</p>\n<p><strong>Degree</strong> = how many entity types are involved:</p>\n<ul>\n<li><strong>Unary:</strong> one entity type related to itself (Employee supervises Employee).</li>\n<li><strong>Binary:</strong> two entity types. The usual case.</li>\n<li><strong>Ternary:</strong> three entity types.</li>\n</ul>\n<p><strong>Modality</strong> is another name for the relationship <strong>minimum</strong> (optional vs required). Cardinality usually means the maximum.</p>\n<h2>Strong, weak, super, sub</h2>\n<ul>\n<li><strong>Strong entity:</strong> has its own identifying attribute.</li>\n<li><strong>Weak entity:</strong> doesn't; depends on an <strong>identifying relationship</strong> to an <strong>identifying entity</strong> (an order line item depends on its order).</li>\n<li>On the diagram, a <strong>diamond</strong> sits next to the identifying entity. Its cardinality there is always <strong>1(1)</strong>.</li>\n<li><strong>Subtype:</strong> a subset of a <strong>supertype</strong> (Manager in Employee). Drawn inside it, linked by an <strong>IsA</strong> relationship.</li>\n<li><strong>Partition:</strong> a group of <strong>mutually exclusive</strong> subtypes (Car, Truck, Motorcycle in Vehicle).</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>\"Apply normal form\" is step 8, in <strong>logical design</strong>, not analysis.</li>\n<li>Weak ≠ intangible. Weak lacks an identifier; intangible isn't stored at all.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. Last of the four analysis steps?</summary><div class=\"ans\"><p><strong>Create supertype and subtype entities.</strong></p></div></details>\n<details class=\"check\"><summary>2. Circle + crow's foot means…?</summary><div class=\"ans\"><p><strong>Zero or many.</strong></p></div></details>\n<details class=\"check\"><summary>3. Relationship type becomes what in logical design?</summary><div class=\"ans\"><p><strong>A foreign key.</strong></p></div></details>\n<details class=\"check\"><summary>4. Students take many classes; classes have many students. Relationship?</summary><div class=\"ans\"><p><strong>Many-to-many.</strong></p></div></details>"}, {"id": "09-normalization", "n": 9, "title": "Primary keys and normalization", "time": "7 minutes", "topic": "logical", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li>Good primary keys are <strong>stable, simple, meaningless</strong>.</li>\n<li>Every kind of table gets its key a specific way: weak = composite, subtype = copies the supertype's, many-to-many = both foreign keys.</li>\n<li><strong>BCNF</strong> = whenever any column depends on B, B is unique. The gold standard.</li>\n</ul></div>\n<h2>Turning the ER model into tables</h2>\n<table>\n<thead>\n<tr>\n<th>ER element</th>\n<th>Becomes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Entity</td>\n<td>Table with a primary key</td>\n</tr>\n<tr>\n<td>One-to-many</td>\n<td>Foreign key on the <strong>many</strong> side</td>\n</tr>\n<tr>\n<td>One-to-one</td>\n<td>Foreign key on one side (usually the table with fewer rows)</td>\n</tr>\n<tr>\n<td>Many-to-many</td>\n<td><strong>New table</strong> (an <strong>associative entity</strong>): two foreign keys = composite primary key</td>\n</tr>\n<tr>\n<td>Plural attribute</td>\n<td>New table with a foreign key back</td>\n</tr>\n<tr>\n<td>Required attribute</td>\n<td>NOT NULL</td>\n</tr>\n<tr>\n<td>Unique attribute</td>\n<td>UNIQUE</td>\n</tr>\n</tbody>\n</table>\n<h2>Choosing a primary key</h2>\n<ul>\n<li><strong>Stable</strong> (doesn't change), <strong>simple</strong> (small, easy to type), <strong>meaningless</strong> (no descriptive info).</li>\n<li><strong>Artificial key:</strong> designer-made, usually an auto-generated integer. Ticks all three boxes.</li>\n<li><strong>Candidate key:</strong> unique <strong>and minimal</strong>. The designer picks one as the primary key.</li>\n<li><strong>Non-key column:</strong> not part of any candidate key.</li>\n</ul>\n<p>Example: for Employee, an auto-generated <code>EmployeeID</code> beats name, email, or phone. Those can change or repeat.</p>\n<h2>Where each table's primary key comes from</h2>\n<table>\n<thead>\n<tr>\n<th>You're building</th>\n<th>Its primary key</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Strong entity</strong> → table</td>\n<td>Its own identifying attribute, or an artificial key</td>\n</tr>\n<tr>\n<td><strong>Weak entity</strong> → weak table</td>\n<td><strong>Composite:</strong> a foreign key to the identifying table + another column</td>\n</tr>\n<tr>\n<td><strong>Subtype entity</strong> → subtype table</td>\n<td><strong>Same as the supertype's</strong> primary key, and it's also a foreign key to the supertype</td>\n</tr>\n<tr>\n<td><strong>Many-to-many</strong> → associative table</td>\n<td><strong>Composite</strong> of the two foreign keys</td>\n</tr>\n</tbody>\n</table>\n<h2>Dependence</h2>\n<ul>\n<li><strong>Functional dependence:</strong> A depends on B if each B value maps to at most one A value (B → A).</li>\n<li><strong>Redundancy:</strong> related values repeated in a table. Normal forms reduce it.</li>\n<li><strong>Trivial dependency:</strong> A's columns are a subset of B's, so A always depends on B.</li>\n</ul>\n<h2>The normal forms</h2>\n<table>\n<thead>\n<tr>\n<th>Form</th>\n<th>Rule</th>\n<th>Plain English</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1NF</strong></td>\n<td>One value per cell, has a primary key, non-key columns depend on it</td>\n<td>No lists in a cell</td>\n</tr>\n<tr>\n<td><strong>2NF</strong></td>\n<td>1NF + non-key columns depend on the <strong>whole</strong> key</td>\n<td>Nothing hangs off half a composite key</td>\n</tr>\n<tr>\n<td><strong>3NF</strong></td>\n<td>Non-key A depends on B → B is unique</td>\n<td>No non-key → non-key dependence</td>\n</tr>\n<tr>\n<td><strong>BCNF</strong></td>\n<td><strong>Any</strong> A depends on B → B is unique</td>\n<td>3NF with \"non-key\" removed</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Example:</strong> <code>Employee(ID, Name, DeptCode, DeptName)</code> breaks 3NF. DeptName depends on DeptCode, which repeats. Fix: move it to <code>Department(DeptCode, DeptName)</code>.</p>\n<ul>\n<li><strong>Normalization:</strong> split tables into higher normal forms. <strong>Last step of logical design.</strong></li>\n<li><strong>Denormalization:</strong> merge tables on purpose, adding redundancy (usually for faster reads).</li>\n<li>BCNF is ideal for tables with frequent inserts, updates, and deletes.</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>In 3NF/BCNF, B must be <strong>unique</strong>, not necessarily minimal, so B isn't always a candidate key.</li>\n<li>A candidate key must be <strong>minimal</strong>; \"unique\" alone isn't enough.</li>\n<li>A subtype table does <strong>not</strong> get a new key. It reuses the supertype's key, which doubles as a foreign key.</li>\n<li>A non-key column that depends on <strong>part</strong> of a composite key breaks <strong>2NF</strong>.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. How do you implement a many-to-many relationship?</summary><div class=\"ans\"><p><strong>A new table holding foreign keys to both tables.</strong></p></div></details>\n<details class=\"check\"><summary>2. Three properties of a good primary key?</summary><div class=\"ans\"><p><strong>Stable, simple, meaningless.</strong></p></div></details>\n<details class=\"check\"><summary>3. Which form drops the word \"non-key\" from 3NF?</summary><div class=\"ans\"><p><strong>BCNF.</strong></p></div></details>\n<details class=\"check\"><summary>4. What's the primary key of a weak table? Of a subtype table?</summary><div class=\"ans\"><p><strong>Weak:</strong> composite, a foreign key to the identifying table plus another column. <strong>Subtype:</strong> the supertype's primary key, which is also a foreign key.</p></div></details>"}, {"id": "10-physical-design", "n": 10, "title": "Physical design", "time": "5 minutes", "topic": "physical", "html": "<div class=\"callout tip\"><p><strong>TL;DR</strong></p>\n<ul>\n<li><strong>Heap</strong> = fast inserts · <strong>sorted</strong> = fast ranges · <strong>hash</strong> = fast exact matches · <strong>cluster</strong> = fast joins.</li>\n<li><strong>High hit ratio → table scan. Low hit ratio → index scan.</strong></li>\n<li><strong>Dense</strong> index = entry per row. <strong>Sparse</strong> = entry per block.</li>\n</ul></div>\n<h2>Table structures</h2>\n<table>\n<thead>\n<tr>\n<th>Structure</th>\n<th>Rows stored</th>\n<th>Best for</th>\n<th>Weak at</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Heap</strong></td>\n<td>No order</td>\n<td>Inserts, bulk loads</td>\n<td>Searching</td>\n</tr>\n<tr>\n<td><strong>Sorted</strong></td>\n<td>By a sort column</td>\n<td>Range queries, ORDER BY</td>\n<td>Inserts</td>\n</tr>\n<tr>\n<td><strong>Hash</strong></td>\n<td>In buckets by hash key</td>\n<td>Exact-match lookups</td>\n<td>Ranges</td>\n</tr>\n<tr>\n<td><strong>Table cluster</strong></td>\n<td>Rows of 2+ tables interleaved</td>\n<td>Joins on the cluster key</td>\n<td>Scanning one table</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Modulo hash:</strong> key ÷ number of buckets, remainder = bucket. Key 46 with 10 buckets → bucket 6.</p>\n<h2>Scans</h2>\n<ul>\n<li><strong>Table scan:</strong> reads table blocks directly, no index.</li>\n<li><strong>Index scan:</strong> reads the index to find which table blocks to read.</li>\n<li><strong>Hit ratio</strong> (filter factor, selectivity): % of rows the query selects.</li>\n<li><strong>Binary search:</strong> split the sorted index in half until you find it.</li>\n</ul>\n<h2>Index types</h2>\n<table>\n<thead>\n<tr>\n<th>Index</th>\n<th>Idea</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Dense</td>\n<td>Entry for every <strong>row</strong></td>\n</tr>\n<tr>\n<td>Sparse</td>\n<td>Entry for every <strong>block</strong> (table sorted on the column)</td>\n</tr>\n<tr>\n<td>Hash</td>\n<td>Entries in buckets</td>\n</tr>\n<tr>\n<td>Bitmap</td>\n<td>Grid of 1s and 0s; great for few distinct values</td>\n</tr>\n<tr>\n<td>Logical</td>\n<td>Stores primary key values, not block pointers</td>\n</tr>\n<tr>\n<td>Function</td>\n<td>Indexes <code>f(column)</code>, like <code>UPPER(Name)</code></td>\n</tr>\n<tr>\n<td>Multi-level</td>\n<td>An index on an index</td>\n</tr>\n</tbody>\n</table>\n<pre><code class=\"language-sql\">CREATE INDEX IdxEmpName ON Employee (Name);\n</code></pre>\n<h2>Storage</h2>\n<ul>\n<li><strong>Tablespace:</strong> maps one or more tables to a single file (<code>CREATE TABLESPACE</code>).</li>\n<li><strong>Partition:</strong> a subset of a table. <strong>Horizontal</strong> splits rows; <strong>vertical</strong> splits columns.</li>\n<li><strong>Storage engine:</strong> does the low-level reads/writes. MySQL default: <strong>InnoDB</strong>.</li>\n</ul>\n<div class=\"callout warning\"><p><strong>Exam traps</strong></p>\n<ul>\n<li>Indexes help <strong>low</strong> hit ratio queries. Selecting most rows? A table scan wins.</li>\n<li>Physical design never changes <strong>results</strong>.</li>\n</ul></div>\n<h2>Quick check</h2>\n<details class=\"check\"><summary>1. Fastest structure for bulk loading?</summary><div class=\"ans\"><p><strong>Heap table.</strong></p></div></details>\n<details class=\"check\"><summary>2. A query returns 90% of rows. Table scan or index scan?</summary><div class=\"ans\"><p><strong>Table scan.</strong></p></div></details>\n<details class=\"check\"><summary>3. Which object maps tables to a single file?</summary><div class=\"ans\"><p><strong>Tablespace.</strong></p></div></details>"}];
